CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER) AS
  CURSOR c IS
    SELECT "No", "Grape", "Winery", "Price", "Score", "Cases"
    FROM wine
    WHERE "Score" >= arg1
    ORDER BY "No" FOR UPDATE;
  running_total NUMBER := 0;
  new_no NUMBER;
  new_price NUMBER;
BEGIN
  FOR rec IN c LOOP
    running_total := running_total + rec."Price";
    IF instr(rec."Grape", 'prefix_') = 1 THEN
      UPDATE wine SET "Price" = arg3 WHERE "No" = rec."No";
    ELSIF rec."No" < arg4 THEN
      DELETE FROM wine WHERE "No" = rec."No";
    ELSIF rec."Winery" = 'Twomey' THEN
      UPDATE wine SET "Price" = arg3 + rec."Price" WHERE "No" = rec."No";
    ELSIF rec."Cases" > rec."Score" THEN
      UPDATE wine SET "Price" = arg3 + rec."Price" WHERE "No" = rec."No";
    ELSE
      UPDATE wine SET "Price" = arg3 * 2 WHERE "No" = rec."No";
    END IF;
  END LOOP;

  SELECT NVL(MAX("No"), 0) + 1 INTO new_no FROM wine;

  IF running_total > arg4 THEN
    new_price := arg3 + 1;
  ELSE
    new_price := arg3;
  END IF;

  INSERT INTO wine ("No", "Score", "Grape", "Price")
  VALUES (new_no, arg1 + 1, 'prefix_' || arg2, new_price);
END;

